#include <stdlib.h>
#include <string.h>
#include "lexer.h"
#include "snow/snow.h"

static void set_input(Ctx* ctx, const char* input) {
  array_clear(&ctx->lexer.buffer);
  array_clear(&ctx->lexer.stack);
  array_clear(&ctx->lexer.saved_stack);
  ctx->lexer.cursor = 0;
  for (size_t i = 0; input[i] != '\0'; ++i) {
    array_append(ctx, &ctx->lexer.buffer, (unsigned char)input[i]);
  }
  // Ensure lookahead never needs stdin; this sentinel is not tokenized.
  array_append(ctx, &ctx->lexer.buffer, '#');
}

static void check_text(Ctx* ctx, TokenType type, const char* expected) {
  Token token = next_token(ctx);
  asserteq(token.type, type);
  asserteq(token.value_type, TEXT);
  asserteq_str(token.value.text, expected);
  free(token.value.text);
}

